// XIAO ESP32S3 の内蔵LEDのピン番号 (GPIO 21)
#define LED_PIN 21

void setup() {
  // LEDピンを出力モードに設定
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, LOW);  // LEDを点灯 (XIAOはLOWで光ります)
  delay(500);                  // 0.5秒待機

  digitalWrite(LED_PIN, HIGH); // LEDを消灯
  delay(500);                  // 0.5秒待機
}
